    @Test
    fun claimCheckerGivesTheSameErrorsAsTheOriginalTool() {
        for (case in claimCases) {
            val actual = ClaimChecker.check(claimTexts.getValue(case.text), item(case.item), brand(case.brand), today = today)
                .errors.map { it.message }
            assertEquals("${case.brand}/${case.item}/${case.text}", case.expected, actual)
        }
    }

