    @Test
    fun linksAreIdenticalToTheOriginalTool() {
        for (case in linkCases) {
            val code = case.code.ifEmpty { null }
            val actual = LinkBuilder.build(brand(case.brand), Channel.fromCode(case.channel), code)
            assertEquals("${case.brand}/${case.channel}/${case.code}", case.expected, actual)
        }
    }

