    @Test
    fun placeholdersAreFilledLikeTheOriginalTool() {
        for (case in fillCases) {
            val code = case.code.ifEmpty { null }
            val actual = Placeholders.fill(fillTemplates[case.template], item(case.item), brand("default"), Channel.fromCode(case.channel), code)
            assertEquals("${case.item}/${case.channel}/${case.code}/${case.template}", case.expected, actual)
        }
    }

